CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','manager','picker','supervisor','director')), full_name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE warehouses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE user_warehouses (user_id uuid NOT NULL REFERENCES users(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), PRIMARY KEY(user_id,warehouse_id));
CREATE TABLE zones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), warehouse_id uuid NOT NULL REFERENCES warehouses(id), code text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(warehouse_id,code), UNIQUE(id,warehouse_id));
CREATE TABLE bins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), warehouse_id uuid NOT NULL REFERENCES warehouses(id), zone_id uuid NOT NULL, code text NOT NULL, active boolean NOT NULL DEFAULT true, FOREIGN KEY(zone_id,warehouse_id) REFERENCES zones(id,warehouse_id), UNIQUE(warehouse_id,code), UNIQUE(id,warehouse_id));
CREATE TABLE suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, contact text);
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sku text NOT NULL UNIQUE, name text NOT NULL, unit text NOT NULL DEFAULT 'шт', barcode text UNIQUE, category text NOT NULL DEFAULT 'Общее', supplier_id uuid REFERENCES suppliers(id), pick_policy text NOT NULL DEFAULT 'FIFO' CHECK(pick_policy IN ('FIFO','FEFO')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_products_name ON products(name);
CREATE TABLE lots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), code text NOT NULL, expires_at date, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id,code), UNIQUE(id,product_id));
CREATE TABLE stock_guards (product_id uuid NOT NULL REFERENCES products(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), PRIMARY KEY(product_id,warehouse_id));
CREATE TABLE stock_movements (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), bin_id uuid NOT NULL, lot_id uuid NOT NULL, qty integer NOT NULL CHECK(qty<>0), doc_type text NOT NULL, doc_id uuid NOT NULL, actor_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(bin_id,warehouse_id) REFERENCES bins(id,warehouse_id), FOREIGN KEY(lot_id,product_id) REFERENCES lots(id,product_id));
CREATE INDEX idx_movements_balance ON stock_movements(product_id,warehouse_id,bin_id,lot_id);
CREATE INDEX idx_movements_doc ON stock_movements(doc_type,doc_id);
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','confirmed','picking','picked','shipped','cancelled')), version integer NOT NULL DEFAULT 1, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), product_id uuid NOT NULL REFERENCES products(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), qty integer NOT NULL CHECK(qty>0));
CREATE INDEX idx_order_lines_order ON order_lines(order_id);
CREATE TABLE reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_line_id uuid NOT NULL REFERENCES order_lines(id), product_id uuid NOT NULL REFERENCES products(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), bin_id uuid NOT NULL REFERENCES bins(id), lot_id uuid NOT NULL REFERENCES lots(id), qty integer NOT NULL CHECK(qty>0), shipped_qty integer NOT NULL DEFAULT 0 CHECK(shipped_qty>=0), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','fulfilled','released','expired')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(shipped_qty<=qty), UNIQUE(order_line_id,warehouse_id,bin_id,lot_id));
CREATE INDEX idx_reservations_active ON reservations(product_id,warehouse_id,status,expires_at);
CREATE TABLE stock_blocks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), bin_id uuid NOT NULL REFERENCES bins(id), lot_id uuid NOT NULL REFERENCES lots(id), qty integer NOT NULL CHECK(qty>0), reason text NOT NULL, active boolean NOT NULL DEFAULT true, actor_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE receipts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid REFERENCES suppliers(id), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted')), created_by uuid NOT NULL REFERENCES users(id), confirmed_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), posted_at timestamptz);
CREATE TABLE receipt_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_id uuid NOT NULL REFERENCES receipts(id), product_id uuid NOT NULL REFERENCES products(id), bin_id uuid NOT NULL REFERENCES bins(id), lot_id uuid NOT NULL REFERENCES lots(id), planned_qty integer NOT NULL CHECK(planned_qty>0), actual_qty integer CHECK(actual_qty>=0), reason text);
CREATE TABLE transfers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), lot_id uuid NOT NULL REFERENCES lots(id), from_bin_id uuid NOT NULL REFERENCES bins(id), to_bin_id uuid NOT NULL REFERENCES bins(id), qty integer NOT NULL CHECK(qty>0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted')), actor_id uuid NOT NULL REFERENCES users(id), posted_at timestamptz, CHECK(from_bin_id<>to_bin_id));
CREATE TABLE pick_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_id uuid NOT NULL UNIQUE REFERENCES reservations(id), order_id uuid NOT NULL REFERENCES orders(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), assigned_to uuid REFERENCES users(id), expected_qty integer NOT NULL CHECK(expected_qty>0), actual_qty integer CHECK(actual_qty>=0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','shortage_pending','completed','accepted','cancelled')), counted_by uuid REFERENCES users(id), approved_by uuid REFERENCES users(id), completed_at timestamptz);
CREATE TABLE shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted')), posted_at timestamptz, confirmed_by uuid REFERENCES users(id), UNIQUE(order_id,warehouse_id));
CREATE TABLE return_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shipment_id uuid NOT NULL REFERENCES shipments(id), reservation_id uuid NOT NULL REFERENCES reservations(id), bin_id uuid NOT NULL REFERENCES bins(id), qty integer NOT NULL CHECK(qty>0), actor_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_counts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), zone_id uuid NOT NULL REFERENCES zones(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), status text NOT NULL DEFAULT 'counting' CHECK(status IN ('counting','submitted','approved')), created_by uuid NOT NULL REFERENCES users(id), counted_by uuid REFERENCES users(id), approved_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz);
CREATE TABLE inventory_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), count_id uuid NOT NULL REFERENCES inventory_counts(id), product_id uuid NOT NULL REFERENCES products(id), bin_id uuid NOT NULL REFERENCES bins(id), lot_id uuid NOT NULL REFERENCES lots(id), snapshot_qty integer NOT NULL, actual_qty integer CHECK(actual_qty>=0), UNIQUE(count_id,product_id,bin_id,lot_id));
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, warehouse_id uuid REFERENCES warehouses(id), before jsonb, after jsonb, request_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_audit_entity ON audit_events(entity_type,entity_id,id);
CREATE TABLE idempotency_records (scope text NOT NULL, key text NOT NULL, payload_hash text NOT NULL, status integer NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope,key));
CREATE TABLE outbox_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, topic text NOT NULL, aggregate_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE OR REPLACE FUNCTION forbid_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Immutable history: corrections must be new entries'; END; $$;
CREATE TRIGGER movements_append_only BEFORE UPDATE OR DELETE ON stock_movements FOR EACH ROW EXECUTE FUNCTION forbid_ledger_mutation();
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION forbid_ledger_mutation();
